import{_ as a,o as l,c as t,a3 as o}from"./chunks/framework.DWfJTVRq.js";const h=JSON.parse('{"title":"여러 프로세스","description":"데이터베이스 파일 하나를 여러 프로세스가 동시에 열어 읽고 쓸 수 있으며, 미리 설정할 것도 프로세스가 죽은 뒤 치울 것도 없습니다.","frontmatter":{"title":"여러 프로세스","order":8,"prev":{"text":"암호화","link":"/ko/guide/encryption"},"next":{"text":"도구","link":"/ko/guide/tools"}},"headers":[{"level":2,"title":"파일을 함께 쓰는 방식","slug":"파일을-함께-쓰는-방식","link":"#파일을-함께-쓰는-방식","children":[]},{"level":2,"title":"잠금 때문에 지킬 규칙","slug":"잠금-때문에-지킬-규칙","link":"#잠금-때문에-지킬-규칙","children":[]},{"level":2,"title":"한 프로세스 안에서","slug":"한-프로세스-안에서","link":"#한-프로세스-안에서","children":[]}],"relativePath":"ko/guide/processes.md","filePath":"ko/guide/processes.md","lastUpdated":1791015517000}'),i={name:"ko/guide/processes.md"};function r(n,e,s,d,c,p){return l(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="여러-프로세스" tabindex="-1">여러 프로세스 <a class="header-anchor" href="#여러-프로세스" aria-label="Permalink to &quot;여러 프로세스&quot;">​</a></h1><p>데이터베이스 파일 하나를 여러 프로세스가 동시에 열어 읽고 쓸 수 있으며, 미리 설정할 것도 프로세스가 죽은 뒤 치울 것도 없습니다.</p><h2 id="파일을-함께-쓰는-방식" tabindex="-1">파일을 함께 쓰는 방식 <a class="header-anchor" href="#파일을-함께-쓰는-방식" aria-label="Permalink to &quot;파일을 함께 쓰는 방식&quot;">​</a></h2><ul><li>한 프로세스가 커밋하면 다른 프로세스에 곧바로 보입니다.</li><li>쓰는 쪽은 한 번에 하나이고, 읽는 쪽은 쓰는 쪽을 기다리지 않습니다.</li><li>쓰기는 다른 프로세스의 쓰기도 같은 프로세스의 것과 똑같이 바쁨 대기 시간만큼 기다리고, 그래도 끝나지 않으면 <code>BUSY</code>로 실패합니다.</li><li>잠시 기다린 쓰기가 다음 차례를 받으므로, 쉬지 않고 커밋하는 프로세스가 다른 프로세스를 계속 밀어내지 못합니다.</li></ul><p>프로세스끼리는 운영체제의 파일 잠금만으로 조율합니다. 공유 메모리도, 잠금 파일도, 서버도 없습니다. 어떤 잠금을 쥔 프로세스가 어느 순간에 죽든 그 잠금은 프로세스와 함께 풀리고, 나머지는 하던 일을 계속합니다. 잠금은 엔진 섹션의 <a href="./../engine/locking">잠금</a>에서 설명합니다.</p><h2 id="잠금-때문에-지킬-규칙" tabindex="-1">잠금 때문에 지킬 규칙 <a class="header-anchor" href="#잠금-때문에-지킬-규칙" aria-label="Permalink to &quot;잠금 때문에 지킬 규칙&quot;">​</a></h2><ul><li><strong>로컬 디스크만.</strong> 잠금과 커밋이 기다리는 동기화는 로컬 디스크에서만 제대로 동작합니다. NFS나 SMB 같은 네트워크 파일 시스템에 있는 데이터베이스는 <code>UNSUPPORTED_FILE_SYSTEM</code>으로 거부합니다.</li><li><strong>파일을 다른 경로로 열지 않기.</strong> 데이터베이스를 연 프로세스 안에서는 복사하려는 목적이라도 그 파일을 따로 열면 안 됩니다. Linux와 macOS에서는 그렇게 연 핸들을 닫는 순간 데이터베이스가 쥔 잠금까지 풀립니다. 열려 있는 데이터베이스를 복사하려면 <a href="./tools#파일-백업하기">백업</a>을 쓰세요.</li><li><strong>iOS App Group 컨테이너.</strong> 앱이 App Group 컨테이너에 데이터베이스를 두었다면, 앱이 일시 중지되기 전에 닫아야 합니다. iOS는 그곳에 잠금을 쥔 채 일시 중지된 앱을 종료합니다.</li></ul><h2 id="한-프로세스-안에서" tabindex="-1">한 프로세스 안에서 <a class="header-anchor" href="#한-프로세스-안에서" aria-label="Permalink to &quot;한 프로세스 안에서&quot;">​</a></h2><p>프로세스 안에서 이미 연 파일을 다시 열면 같은 데이터베이스의 핸들이 하나 더 생깁니다. 핸들끼리는 페이지 캐시와 쓰기를 함께 쓰고, 엔진은 파일마다 운영체제 핸들을 하나만 둡니다. 핸들은 열 때 받은 스키마를 계속 쓰며, 다른 핸들이나 프로세스가 파일을 마이그레이션한 뒤에는 <code>SCHEMA_MISMATCH</code>로 실패합니다.</p><div class="lang-only" data-code-lang="node"><p>Electron에서도 앱 인스턴스 여럿이나 메인 프로세스와 유틸리티 프로세스가 같은 방식으로 파일을 함께 씁니다. Electron에서만 챙길 점은 <a href="./electron">Electron</a>에 있습니다.</p></div><div class="lang-only" data-code-lang="dart"><p>Flutter 앱에서는 isolate 여럿이 같은 방식으로 파일을 함께 씁니다. isolate마다 <code>Database</code>를 따로 열고, 핸들끼리는 프로세스의 페이지 캐시와 쓰기를 함께 씁니다. 한 isolate의 비동기 쓰기는 서로 차례를 지키고, 다른 isolate의 쓰기는 다른 프로세스의 쓰기처럼 엔진 안에서 그 차례를 기다립니다.</p></div>',11)])])}const _=a(i,[["render",r]]);export{h as __pageData,_ as default};
